// ODT Templates
const TEMPLATE_STYLES_B64 = "";
const TEMPLATE_MANIFEST_B64 = "";
const TEMPLATE_IMAGE_B64 = "";

const TEMPLATE_CONTENT_XML = `<?xml version='1.0' encoding='UTF-8'?>
<office:document-content xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" xmlns:meta="urn:oasis:names:tc:opendocument:xmlns:meta:1.0" xmlns:style="urn:oasis:names:tc:opendocument:xmlns:style:1.0" xmlns:fo="urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0" xmlns:draw="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0" xmlns:xlink="http://www.w3.org/1999/xlink" xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0" xmlns:chart="urn:oasis:names:tc:opendocument:xmlns:chart:1.0" xmlns:presentation="urn:oasis:names:tc:opendocument:xmlns:presentation:1.0" xmlns:table="urn:oasis:names:tc:opendocument:xmlns:table:1.0" office:version="1.2"><office:automatic-styles/><office:body><office:text><text:p text:style-name="Center"><draw:frame svg:width="8.8cm" svg:height="4.2cm"><draw:image xlink:href="Pictures/0591495A461F4991A09C58DF8BF777C2.jpg"/></draw:frame></text:p><text:p text:style-name="Center"><text:span text:style-name="HeaderText">UNIVERSIDADE FEDERAL DO PARANÁ</text:span></text:p><text:p text:style-name="Center"><text:span text:style-name="HeaderText">Rua XV de Novembro, 1299,  - Bairro Centro, Curitiba/PR, CEP 80060-000</text:span></text:p><text:p text:style-name="Center"><text:span text:style-name="HeaderText">Telefone: (41) 3360-5000  - ufpr.br</text:span></text:p><text:p/><text:p/><text:p text:style-name="Center"><text:span text:style-name="TitleText">CERTIFICADO</text:span></text:p><text:p/><text:p/><text:p text:style-name="Justify"><text:span text:style-name="BodyText">[[BODY_CONTENT]]</text:span></text:p><text:p/><text:p/><text:p/><text:p/><text:p text:style-name="Right"><text:span text:style-name="BodyText">Curitiba, 25 de junho de 2026.</text:span></text:p><text:p/><text:p/><text:p/><text:p/><text:p text:style-name="Center"><text:span text:style-name="Bold">MARIA STAEL BITTENCOURT MADUREIRA</text:span></text:p><text:p text:style-name="Center"><text:span text:style-name="BodyText">COORDENADORA DE APOIO A PROJETOS, PROGRAMAS E ESTÁGIOS - COAPPE</text:span></text:p><text:p text:style-name="Center"><text:span text:style-name="BodyText">PRÓ - REITORIA DE GRADUAÇÃO E ENSINO PROFISSIONAL – PROGRAP</text:span></text:p></office:text></office:body></office:document-content>`;

// Elements
const dropZone = document.getElementById('drop-zone');
const fileInput = document.getElementById('file-input');
const progressArea = document.getElementById('progress-area');
const resultArea = document.getElementById('result-area');
const statusText = document.getElementById('status-text');
const progressPercent = document.getElementById('progress-percent');
const progressFill = document.getElementById('progress-fill');
const finalCount = document.getElementById('final-count');
const downloadBtn = document.getElementById('download-btn');
const errorsContainer = document.getElementById('errors-container');
const errorsList = document.getElementById('errors-list');

let finalZipBlob = null;

// Drag and Drop Logic
dropZone.addEventListener('click', () => fileInput.click());

dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.classList.add('dragover');
});

dropZone.addEventListener('dragleave', () => {
    dropZone.classList.remove('dragover');
});

dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.classList.remove('dragover');
    if (e.dataTransfer.files.length > 0) {
        handleFile(e.dataTransfer.files[0]);
    }
});

fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
        handleFile(e.target.files[0]);
    }
});

function escapeXml(unsafe) {
    return unsafe.replace(/[<>&'"]/g, function (c) {
        switch (c) {
            case '<': return '&lt;';
            case '>': return '&gt;';
            case '&': return '&amp;';
            case '\'': return '&apos;';
            case '"': return '&quot;';
        }
    });
}

function normalizeLocal(text) {
    if (!text) return "";
    text = String(text).trim();
    text = text.replace(/["']/g, '');
    text = text.replace(/^[^a-zA-Z0-9À-ÿ]+|[^a-zA-Z0-9À-ÿ]+$/g, '');
    text = text.replace(/\s+/g, ' ');
    if (text.length > 0) {
        text = text.charAt(0).toUpperCase() + text.slice(1);
    }
    return text;
}

function normalizeFilename(text) {
    if (!text) return "";
    text = String(text).normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    text = text.toLowerCase().trim();
    text = text.replace(/\s+/g, '_');
    text = text.replace(/[^\w]/g, '');
    return text;
}

async function createOdtBlob(bodyHtml) {
    const zip = new JSZip();
    
    zip.file("mimetype", "application/vnd.oasis.opendocument.text");
    zip.folder("META-INF").file("manifest.xml", TEMPLATE_MANIFEST_B64, {base64: true});
    zip.file("styles.xml", TEMPLATE_STYLES_B64, {base64: true});
    zip.folder("Pictures").file("0591495A461F4991A09C58DF8BF777C2.jpg", TEMPLATE_IMAGE_B64, {base64: true});
    
    // Parse <b> tags into ODT bold spans
    let parts = bodyHtml.split(/(<b>|<\/b>)/);
    let odtText = "";
    let isBold = false;
    
    for (let p of parts) {
        if (p === '<b>') isBold = true;
        else if (p === '</b>') isBold = false;
        else if (p) {
            let escaped = escapeXml(p);
            if (isBold) {
                odtText += `<text:span text:style-name="Bold">${escaped}</text:span>`;
            } else {
                odtText += escaped;
            }
        }
    }
    
    let content = TEMPLATE_CONTENT_XML.replace('[[BODY_CONTENT]]', odtText);
    zip.file("content.xml", content);
    
    return await zip.generateAsync({type: "blob"});
}

async function handleFile(file) {
    if (!file.name.endsWith('.xlsx')) {
        alert('Por favor, selecione um arquivo .xlsx válido.');
        return;
    }
    
    dropZone.classList.add('hidden');
    progressArea.classList.remove('hidden');
    
    const reader = new FileReader();
    reader.onload = async (e) => {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, {type: 'array'});
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        
        // Use defval to ensure empty cells come up as empty strings
        const rows = XLSX.utils.sheet_to_json(worksheet, {defval: ""});
        
        const mainZip = new JSZip();
        let gerados = 0;
        let invalidos = [];
        
        const total = rows.length;
        
        for (let i = 0; i < total; i++) {
            let percent = Math.round((i / total) * 100);
            statusText.textContent = `Gerando certificado ${i + 1} de ${total}...`;
            progressPercent.textContent = `${percent}%`;
            progressFill.style.width = `${percent}%`;
            
            // Allow UI to update
            if (i % 10 === 0) await new Promise(r => setTimeout(r, 0));
            
            const row = rows[i];
            let localRaw = row['Local de atividades'] || '';
            
            if (!localRaw || String(localRaw).trim() === '-' || String(localRaw).trim() === '') {
                invalidos.push(row['Discente'] || `Linha ${i+2}`);
                continue;
            }
            
            let local_norm = normalizeLocal(localRaw);
            
            let dados = {
                nome_estudante: String(row['Discente']).trim(),
                matricula_estudante: String(row['GRR']).trim(),
                nome_orientador: String(row['Nome docente']).trim(),
                matricula_orientador: String(row['Matrícula SIAD docente']).trim(),
                programa: String(row['Tipo'] || 'PROGRAMA DE VOLUNTARIADO ACADÊMICO').trim(),
                data_inicio: String(row['Início']).trim(),
                data_fim: String(row['Fim']).trim(),
                horas_semanais: String(row['Carga Horaria Semanal']).trim(),
                horas_totais: String(row['Carga Horaria Total']).trim(),
                projeto: local_norm
            };
            
            // Aluno
            if (dados.nome_estudante && dados.nome_estudante !== '-') {
                let hrs_sem = String(dados.horas_semanais).padStart(2, '0');
                let html_text = `Certificamos que o(a) estudante <b>${dados.nome_estudante}</b>, com matrícula nº <b>${dados.matricula_estudante}</b>, desenvolveu <b>${hrs_sem}</b> horas semanais de atividades no <b>${dados.programa}</b>, no período de <b>${dados.data_inicio}</b> a <b>${dados.data_fim}</b>, totalizando <b>${dados.horas_totais}</b> horas, no <b>${dados.projeto}</b>, sob a orientação do(a) Professor(a) <b>${dados.nome_orientador}</b>, com matrícula nº <b>${dados.matricula_orientador}</b>.`;
                
                let blob = await createOdtBlob(html_text);
                mainZip.file(`certificado_aluno_${normalizeFilename(dados.nome_estudante)}.odt`, blob);
                gerados++;
            }
            
            // Orientador
            if (dados.nome_orientador && dados.nome_orientador !== '-' && dados.matricula_orientador !== '0') {
                let hrs_sem = String(dados.horas_semanais).padStart(2, '0');
                let html_text = `Certificamos que o(a) Professor(a) <b>${dados.nome_orientador}</b>, com matrícula nº <b>${dados.matricula_orientador}</b>, orientou, no <b>${dados.programa}</b>, o(a) estudante <b>${dados.nome_estudante}</b>, com matrícula nº <b>${dados.matricula_estudante}</b>, no período de <b>${dados.data_inicio}</b> a <b>${dados.data_fim}</b>, no <b>${dados.projeto}</b>, com carga horária semanal de <b>${hrs_sem}</b> horas, totalizando <b>${dados.horas_totais}</b> horas.`;
                
                let blob = await createOdtBlob(html_text);
                mainZip.file(`certificado_professor_${normalizeFilename(dados.nome_orientador)}_orientando_${normalizeFilename(dados.nome_estudante)}.odt`, blob);
                gerados++;
            }
        }
        
        statusText.textContent = "Empacotando arquivo ZIP...";
        progressPercent.textContent = "100%";
        progressFill.style.width = "100%";
        
        finalZipBlob = await mainZip.generateAsync({type: "blob"});
        
        progressArea.classList.add('hidden');
        resultArea.classList.remove('hidden');
        finalCount.textContent = `Concluído! ${gerados} certificados gerados.`;
        
        if (invalidos.length > 0) {
            errorsContainer.classList.remove('hidden');
            errorsList.innerHTML = invalidos.map(nome => `<tr><td>${escapeXml(nome)}</td></tr>`).join('');
        }
    };
    
    reader.readAsArrayBuffer(file);
}

downloadBtn.addEventListener('click', () => {
    if (finalZipBlob) {
        saveAs(finalZipBlob, "Certificados.zip");
    }
});
